python3 -c "
import json
with open('/app/resources/treasury_bulletin_2011_12.json') as f:
    data = json.load(f)

def search_elements(elements, text, depth=0):
    results = []
    for el in elements:
        if el.get('content') and text.lower() in el['content'].lower():
            results.append(el)
        if 'elements' in el:
            results.extend(search_elements(el['elements'], text, depth+1))
    return results

results = search_elements(data['document']['elements'], 'Department of Labor')
for r in results:
    print(r.get('content', ''))
"

